10: package org.openmrs.module.queue.web;
11: 
12: import java.util.Date;
13: import java.util.Optional;
14: 
15: import org.openmrs.Concept;
16: import org.openmrs.api.APIException;
17: import org.openmrs.module.queue.api.QueueEntryService;
18: import org.openmrs.module.queue.api.QueueServicesWrapper;
19: import org.openmrs.module.queue.model.Queue;
20: import org.openmrs.module.queue.model.QueueEntry;
21: import org.openmrs.module.queue.model.QueueEntryTransition;
22: import org.openmrs.module.queue.web.dto.QueueEntryTransitionRequest;
23: import org.openmrs.module.queue.web.dto.UndoQueueEntryTransitionRequest;
24: import org.openmrs.module.webservices.rest.web.ConversionUtil;
25: import org.openmrs.module.webservices.rest.web.RestConstants;
26: import org.openmrs.module.webservices.rest.web.representation.Representation;
27: import org.openmrs.module.webservices.rest.web.v1_0.controller.BaseRestController;
28: import org.springframework.beans.factory.annotation.Autowired;
29: import org.springframework.stereotype.Controller;
30: import org.springframework.web.bind.annotation.RequestBody;
31: import org.springframework.web.bind.annotation.RequestMapping;
32: import org.springframework.web.bind.annotation.RequestMethod;
33: import org.springframework.web.bind.annotation.ResponseBody;
34: 
35: /**
36:  * The main controller that exposes additional end points for order entry
37:  */
38: @Controller
39: public class QueueEntryTransitionRestController extends BaseRestController {
40: 	
41: 	private final QueueServicesWrapper services;
42: 	
43: 	@Autowired
44: 	public QueueEntryTransitionRestController(QueueServicesWrapper services) {
45: 		this.services = services;
46: 	}
47: 	
48: 	@RequestMapping(value = "/rest/" + RestConstants.VERSION_1 + "/queue-entry/transition", method = { RequestMethod.PUT,
49: 	        RequestMethod.POST })
50: 	@ResponseBody
51: 	public Object transitionQueueEntry(@RequestBody QueueEntryTransitionRequest body) {
52: 		QueueEntryTransition transition = new QueueEntryTransition();
53: 		
54: 		// Queue Entry to Transition
55: 		String queueEntryUuid = body.getQueueEntryToTransition();
56: 		QueueEntry queueEntry = services.getQueueEntryService().getQueueEntryByUuid(queueEntryUuid)
57: 		        .orElseThrow(() -> new APIException("queueEntryToTransition not specified or found"));
58: 		transition.setQueueEntryToTransition(queueEntry);
59: 		
60: 		// Transition date is always the server's current time. Any client-supplied transitionDate is
61: 		// intentionally ignored to avoid clock-skew artifacts between the old entry's ended_at and the
62: 		// new entry's started_at.
63: 		transition.setTransitionDate(new Date());
64: 		
65: 		// Queue
66: 		if (body.getNewQueue() != null) {
